                <h2 style={{ margin: 0, fontSize: "16pt", fontWeight: 800, color: "#1e3a8a", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                  LIVINCART PROJECT QUOTATION
                </h2>
                <p style={{ margin: "2px 0 0 0", fontSize: "9pt", color: "#64748b" }}>
