                <div><strong>Quotation Ref:</strong> {rId}</div>
                <div><strong>Date:</strong> {formatDisplayDate(dVal)}</div>
                <div><strong>Place:</strong> {place}</div>
              </div>
            </div>

            {/* Client & Project Overview */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "16px", backgroundColor: "#f8fafc", padding: "12px 16px", borderRadius: "6px", marginBottom: "20px", fontSize: "9pt", border: "1px solid #e2e8f0" }}>
              <div>
                <div style={{ color: "#64748b", fontSize: "8pt", textTransform: "uppercase", fontWeight: 700, marginBottom: "2px" }}>Client & Site Info</div>
                <div style={{ fontWeight: 800, fontSize: "10pt", color: "#0f172a" }}>{cName}</div>
                <div style={{ color: "#334155" }}>{addrVal}</div>
