                <div><strong>Quotation Value:</strong> ₹{valAmt}</div>
                <div style={{ fontSize: "8pt", color: "#2563eb", fontWeight: 700 }}>({wordsVal || convertNumberToWords(valAmt)})</div>
              </div>
            </div>

            {/* Scope Breakdown Table */}
            <h3 style={{ fontSize: "11pt", fontWeight: 800, color: "#1e3a8a", margin: "0 0 10px 0" }}>
              1. Quotation Scope & Financial Summary
            </h3>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "9pt", marginBottom: "20px" }}>
              <thead>
                <tr style={{ backgroundColor: "#1e3a8a", color: "#ffffff", fontWeight: 700 }}>
                  <th style={{ padding: "8px 10px", textAlign: "left", width: "8%" }}>S.No</th>
                  <th style={{ padding: "8px 10px", textAlign: "left", width: "52%" }}>Category / Scope Description</th>
                  <th style={{ padding: "8px 10px", textAlign: "left", width: "20%" }}>Execution Stage</th>
                  <th style={{ padding: "8px 10px", textAlign: "right", width: "20%" }}>Estimated Amount (₹)</th>
