              </thead>
              <tbody>
                <tr style={{ borderBottom: "1px solid #e2e8f0" }}>
                  <td style={{ padding: "8px 10px" }}>1</td>
                  <td style={{ padding: "8px 10px", fontWeight: 700 }}>Primary Woodwork & Custom Modular Solutions</td>
                  <td style={{ padding: "8px 10px" }}>Production & Assembly</td>
                  <td style={{ padding: "8px 10px", textAlign: "right", fontWeight: 700 }}>As per BOQ</td>
                </tr>
                <tr style={{ borderBottom: "1px solid #e2e8f0" }}>
                  <td style={{ padding: "8px 10px" }}>2</td>
                  <td style={{ padding: "8px 10px", fontWeight: 700 }}>Hardware, Fitting Accessories & Edge Banding</td>
                  <td style={{ padding: "8px 10px" }}>Procurement</td>
                  <td style={{ padding: "8px 10px", textAlign: "right", fontWeight 700 }}>Included</td>
                </tr>
                <tr style={{ borderBottom: "1px solid #e2e8f0" }}>
                  <td style={{ padding: "8px 10px" }}>3</td>
                  <td style={{ padding: "8px 10px", fontWeight 700 }}>Site Execution, Transportation & Installation</td>
                  <td style={{ padding: "8px 10px" }}>On-Site Work</td>
                  <td style={{ padding: "8px 10px", textAlign: "right", fontWeight 700 }}>Included</td>
                </tr>
                <tr style={{ backgroundColor: "#f1f5f9", fontWeight: 800 }}>
                  <td colSpan={3} style={{ padding: "10px", textAlign: "right", fontSize: "9.5pt" }}>Grand Total Quote Estimate:</td>
                  <td style={{ padding: "10px", textAlign: "right", color: "#1e3a8a", fontSize: "10.5pt" }}>₹{valAmt}</td>
                </tr>
