// Helper to extract live quotation total from localStorage drafts or server quotes
const getQuotationTotalForEntity = (projId: any, clientName: string, quotesByProjId: Map<string, any>, quotesByClient: Map<string, any>) => {
  try {
    const pStr = String(projId || '').replace(/[^0-9a-zA-Z_-]/g, '');
    const cKey = String(clientName || '').toLowerCase().trim();

    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith('quote_draft_')) {
        const item = localStorage.getItem(k);
        if (item) {
          const parsed = JSON.parse(item);
          const pFor = String(parsed?.proposalFor || '').toLowerCase().trim();
          if ((pStr && pStr.length > 1 && k.includes(pStr)) || (cKey && cKey.length > 2 && (k.toLowerCase().includes(cKey) || pFor.includes(cKey)))) {
            if (parsed && parsed.sections && Array.isArray(parsed.sections)) {
              let subtotal = 0;
              parsed.sections.forEach((s: any) => {
                (s.items || []).forEach((it: any) => {
                  const amt = parseFloat(it.amount);
                  if (!isNaN(amt) && amt > 0) subtotal += amt;
                  else subtotal += (parseFloat(it.quantity) || 1) * (parseFloat(it.rate) || 0);
                });
              });
              const disc = (subtotal * (parseFloat(parsed.discountPercent) || 0)) / 100;
              const total = Math.round(subtotal - disc);
              if (total > 0) return total;
            }
          }
        }
      }
    }
  } catch (e) {}

  const matched = quotesByProjId.get(String(projId)) || quotesByClient.get(String(clientName || '').toLowerCase().trim());
  if (matched && parseFloat(matched.total_amount || 0) > 0) {
    return parseFloat(matched.total_amount);
  }

  return 0;
};

