const fetchAgreements = async () => {
  setLoading(true);
  try {
    // Fetch saved agreements, active projects, sales leads, AND quotes so ALL quotation entries & totals automatically reflect!
    const [agRes, projRes, leadsRes, quotesRes] = await Promise.all([
      fetch(`${API_BASE_URL}/agreements`).then(r => r.json()).catch(() => ({ success: false, data: [] })),
      fetch(`${API_BASE_URL}/projects`).then(r => r.json()).catch(() => ({ success: false, data: [] })),
      fetch(`${API_BASE_URL}/leads`).then(r => r.json()).catch(() => ({ success: false, data: [] })),
      fetch(`${API_BASE_URL}/quotes`).then(r => r.json()).catch(() => ({ success: false, data: [] }))
    ]);

    const savedAgreements = agRes.success ? (agRes.data || []) : [];
    const projects = projRes.success ? (projRes.data || []) : [];
    const leads = Array.isArray(leadsRes) ? leadsRes : (leadsRes.success ? (leadsRes.data || []) : []);
    const quotes = Array.isArray(quotesRes) ? quotesRes : (quotesRes.success ? (quotesRes.data || []) : []);

    // Build quick lookup maps for quotes by project_id and client_name
    const quotesByProjId = new Map<string, any>();
    const quotesByClient = new Map<string, any>();
    const matchedQuoteIds = new Set<string>();

    quotes.forEach((q: any) => {
      if (q.quote_id) {
        if (q.project_id) quotesByProjId.set(String(q.project_id), q);
        const cKey = String(q.client_name || q.subtitle || '').trim().toLowerCase();
        if (cKey && cKey !== 'client') quotesByClient.set(cKey, q);
      }
    });

    const existingRefIds = new Set<string>();
    const existingClientNames = new Set<string>();

    // 1. Process Saved Agreements (override contract_value from Quote if quote exists)
    const updatedSavedAgreements = savedAgreements.map((a: any) => {
      existingRefIds.add(a.ref_id);
      const cKey = String(a.client_name || '').trim().toLowerCase();
      if (cKey) existingClientNames.add(cKey);

      const matchedQuote = quotesByProjId.get(String(a.project_id)) || quotesByClient.get(cKey);
      if (matchedQuote) {
        matchedQuoteIds.add(String(matchedQuote.quote_id));
        const qVal = parseFloat(matchedQuote.total_amount || 0);
        const currentVal = parseFloat(String(a.contract_value || '0').replace(/,/g, ''));
        if (qVal > 0 && (currentVal === 0 || isNaN(currentVal))) {
          return {
            ...a,
            contract_value: qVal.toLocaleString(),
            contract_value_words: convertNumberToWords(qVal)
          };
        }
      }
      return a;
    });

    // 2. Process Projects (use Quotation Total if quote exists)
    const projectAgreements = projects.map((p: any) => {
      const refCode = p.project_code || `PR_${p.project_id}`;
      const cName = p.client_name || p.project_name || 'Client';
      const cKey = cName.trim().toLowerCase();

      if (!existingRefIds.has(refCode) && !existingClientNames.has(cKey)) {
        const matchedQuote = quotesByProjId.get(String(p.project_id)) || quotesByClient.get(cKey);
        if (matchedQuote) matchedQuoteIds.add(String(matchedQuote.quote_id));

        const rawVal = matchedQuote && parseFloat(matchedQuote.total_amount || 0) > 0 
          ? parseFloat(matchedQuote.total_amount || 0) 
          : parseFloat(p.total_budget || 0);

        return {
          id: `proj_${p.project_id}`,
          isFromProject: true,
          project_id: p.project_id,
          ref_id: refCode,
          project_type: p.project_type || 'Interior Design',
          client_name: cName,
          address: p.site_address || 'Visakhapatnam',
          contract_value: rawVal > 0 ? rawVal.toLocaleString() : "0",
          contract_value_words: convertNumberToWords(rawVal),
          date: p.start_date || (p.created_at ? p.created_at.split('T')[0] : new Date().toISOString().split('T')[0]),
          place: 'Visakhapatnam',
          status: p.status === 'completed' ? 'Signed' : (p.status || 'Created'),
          payment_date: '-'
        };
      }
      return null;
    }).filter(Boolean);

    projectAgreements.forEach((pa: any) => {
      if (pa) {
        existingRefIds.add(pa.ref_id);
        existingClientNames.add(String(pa.client_name || '').toLowerCase().trim());
      }
    });

    // 3. Process Sales Leads (use Quotation Total if quote exists)
    const leadAgreements = leads.map((l: any, idx: number) => {
      const leadId = l.lead_id || l.id || `lead_${idx}`;
      const refCode = `PR_LEAD_${leadId}`;
      const cName = l.name || l.client_name || l.lead_name || 'Sales Lead';
      const cKey = cName.trim().toLowerCase();

      if (!existingRefIds.has(refCode) && !existingClientNames.has(cKey) && cKey !== 'sales lead') {
        const matchedQuote = quotesByProjId.get(String(leadId)) || quotesByClient.get(cKey);
        if (matchedQuote) matchedQuoteIds.add(String(matchedQuote.quote_id));

        const rawVal = matchedQuote && parseFloat(matchedQuote.total_amount || 0) > 0 
          ? parseFloat(matchedQuote.total_amount || 0) 
          : parseFloat(l.budget || l.estimated_value || l.contract_value || 0);

        return {
          id: `lead_${leadId}`,
          isFromLead: true,
          lead_id: leadId,
          ref_id: refCode,
          project_type: l.project_type || l.project_scope || 'Interior Design',
          client_name: cName,
          address: l.address || l.site_address || l.location || 'Visakhapatnam',
          contract_value: rawVal > 0 ? rawVal.toLocaleString() : "0",
          contract_value_words: convertNumberToWords(rawVal),
          date: l.created_at ? l.created_at.split('T')[0] : new Date().toISOString().split('T')[0],
          place: 'Visakhapatnam',
          status: l.status === 'converted' || l.status === 'won' ? 'Signed' : 'Created',
          payment_date: '-'
        };
      }
      return null;
    }).filter(Boolean);

    leadAgreements.forEach((la: any) => {
      if (la) {
        existingRefIds.add(la.ref_id);
        existingClientNames.add(String(la.client_name || '').toLowerCase().trim());
      }
    });

    // 4. Process Standalone Quotations created on /quotes page
    const standaloneQuoteAgreements = quotes.map((q: any, idx: number) => {
      if (q.quote_id && !matchedQuoteIds.has(String(q.quote_id))) {
        const refCode = q.quote_number || `QTN_${q.quote_id}`;
        const cName = q.client_name || q.subtitle || `Quotation #${q.quote_id}`;
        const cKey = cName.trim().toLowerCase();

        if (!existingRefIds.has(refCode) && !existingClientNames.has(cKey)) {
          const rawVal = parseFloat(q.total_amount || 0);
          return {
            id: `quote_${q.quote_id}`,
            isFromQuote: true,
            quote_id: q.quote_id,
            project_id: q.project_id,
            ref_id: refCode,
            project_type: q.project_type || 'Interior Design',
            client_name: cName,
            address: q.address || 'Visakhapatnam',
            contract_value: rawVal > 0 ? rawVal.toLocaleString() : "0",
            contract_value_words: convertNumberToWords(rawVal),
            date: q.created_at ? q.created_at.split('T')[0] : new Date().toISOString().split('T')[0],
            place: 'Visakhapatnam',
            status: 'Created',
            payment_date: '-'
          };
        }
      }
      return null;
    }).filter(Boolean);

    setAgreements([...updatedSavedAgreements, ...projectAgreements, ...leadAgreements, ...standaloneQuoteAgreements]);
  } catch (err) {
    console.error("Error fetching agreements, projects, leads & quotes:", err);
  } finally {
    setLoading(false);
  }
};

